    <?php if (!empty($concluidos)): foreach ($concluidos as $expedicao): $pedido=$expedicao['pedido'] ?? []; $status=strtolower((string)($pedido['status'] ?? 'expedicao')); $expedidoTimestamp=!empty($expedicao['data_expedicao'])?strtotime((string)$expedicao['data_expedicao']):false; ?>
